$percentToBps=static function(mixed$value):int{
    $raw=str_replace(',','.',trim((string)$value));
    if($raw===''||!is_numeric($raw))throw new RuntimeException('Informe um percentual válido.');
    $bps=(int)round((float)$raw*100);
    if($bps<0||$bps>10000)throw new RuntimeException('A taxa deve ficar entre 0% e 100%.');
    return$bps;
};
$moneyToCents=static function(mixed$value):int{
    $raw=trim((string)$value);if($raw==='')return 0;$negative=str_starts_with($raw,'-');$raw=str_replace(['R$',' ','-'],'',$raw);if(str_contains($raw,',')&&str_contains($raw,'.'))$raw=str_replace('.','',$raw);$raw=str_replace(',','.',$raw);$cents=(int)round((float)$raw*100);return$negative?-$cents:$cents;
};

