            $id=(int)($_POST['id']??0);$name=mb_substr(trim((string)($_POST['name']??'')),0,160);$scope=(string)($_POST['scope_type']??'default');$allowed=['default','tenant','city','state','plan','campaign'];if(!in_array($scope,$allowed,true))throw new RuntimeException('Tipo de regra inválido.');if($name==='')throw new RuntimeException('Informe o nome da regra.');$rateBps=$percentToBps($_POST['rate_percent']??'');$priority=max(-100000,min(100000,(int)($_POST['priority']??0)));$tenantId=$scope==='tenant'?max(0,(int)($_POST['tenant_id']??0)):null;$city=$scope==='city'?mb_substr(trim((string)($_POST['city']??'')),0,120):null;$state=$scope==='state'?mb_substr(mb_strtoupper(trim((string)($_POST['state']??''))),0,2):null;$plan=$scope==='plan'?mb_substr(trim((string)($_POST['plan_code']??'')),0,60):null;$campaign=$scope==='campaign'?mb_substr(trim((string)($_POST['campaign_code']??'')),0,80):null;$starts=trim((string)($_POST['starts_at']??''))?:null;$ends=trim((string)($_POST['ends_at']??''))?:null;if($scope==='tenant'&&!$tenantId)throw new RuntimeException('Selecione a empresa.');if($scope==='city'&&!$city)throw new RuntimeException('Informe a cidade.');if($scope==='state'&&!$state)throw new RuntimeException('Informe o estado.');if($scope==='plan'&&!$plan)throw new RuntimeException('Selecione o plano.');if($scope==='campaign'&&!$campaign)throw new RuntimeException('Informe o código da campanha.');if($starts&&$ends&&strtotime($ends)<strtotime($starts))throw new RuntimeException('A data final não pode ser anterior à inicial.');
            if($id>0){$q=$pdo->prepare('UPDATE marketplace_commission_rules SET name=?,scope_type=?,tenant_id=?,city=?,state=?,plan_code=?,campaign_code=?,rate_bps=?,priority=?,starts_at=?,ends_at=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$q->execute([$name,$scope,$tenantId,$city,$state,$plan,$campaign,$rateBps,$priority,$starts,$ends,$id]);}else{$q=$pdo->prepare('INSERT INTO marketplace_commission_rules (name,scope_type,tenant_id,city,state,plan_code,campaign_code,rate_bps,priority,starts_at,ends_at,active,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,1,?)');$q->execute([$name,$scope,$tenantId,$city,$state,$plan,$campaign,$rateBps,$priority,$starts,$ends,Auth::id()]);$id=(int)$pdo->lastInsertId();}
