        if($action==='invoice-generate'){$tenantId=(int)($_POST['tenant_id']??0);$start=(string)($_POST['period_start']??'');$end=(string)($_POST['period_end']??'');$due=(string)($_POST['due_at']??'');$invoice=Database::transaction(function(PDO$tx)use($tenantId,$start,$end,$due,$billing):array{(new MarketplaceReconciliationService())->reconcileTenant($tx,$tenantId,2000);return$billing->generate($tx,$tenantId,$start,$end,$due?:null);});Auth::audit('platform.invoice_generated','platform_invoice',(string)$invoice['id'],['tenant_id'=>$tenantId,'period_start'=>$start,'period_end'=>$end]);em_flash('ok','Fatura atualizada com mensalidade e comissões elegíveis.');em_go('marketplace-finance',['invoice'=>(int)$invoice['id'],'tab'=>'invoices']);}
