        if($action==='invoice-adjustment'){$invoiceId=(int)($_POST['invoice_id']??0);$tenantId=(int)($_POST['tenant_id']??0);$kind=(string)($_POST['kind']??'service');$amount=abs($moneyToCents($_POST['amount']??0));if($amount<=0)throw new RuntimeException('Informe um valor maior que zero.');if($kind==='credit')$amount=-$amount;$description=mb_substr(trim((string)($_POST['description']??'')),0,500);$reference='manual:'.bin2hex(random_bytes(12));Database::transaction(fn(PDO$tx)=>$billing->addAdjustment($tx,$invoiceId,$tenantId,$description,$amount,$reference));Auth::audit('platform.invoice_adjustment','platform_invoice',(string)$invoiceId,['tenant_id'=>$tenantId,'amount_cents'=>$amount]);em_flash('ok',$amount<0?'Crédito adicionado.':'Serviço adicional incluído.');em_go('marketplace-finance',['invoice'=>$invoiceId,'tab'=>'invoices']);}
        if($action==='impulsiona-toggle'){$tenantId=(int)($_POST['tenant_id']??0);$participates=isset($_POST['participates'])?1:0;Database::transaction(function(PDO$tx)use($tenantId,$participates):void{$s=$tx->prepare('SELECT tenant_id FROM marketplace_promotion_accounts WHERE tenant_id=?');$s->execute([$tenantId]);if($s->fetchColumn())$tx->prepare('UPDATE marketplace_promotion_accounts SET participates=?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=?')->execute([$participates,$tenantId]);else$tx->prepare('INSERT INTO marketplace_promotion_accounts (tenant_id,participates,balance_cents) VALUES (?,?,0)')->execute([$tenantId,$participates]);});Auth::audit('marketplace.impulsiona_status','tenant',(string)$tenantId,['participates'=>$participates]);em_flash('ok','EventMenu Impulsiona atualizado.');em_go('marketplace-finance',['company'=>$tenantId]);}
        if($action==='impulsiona-entry'){$tenantId=(int)($_POST['tenant_id']??0);$type=(string)($_POST['entry_type']??'adjustment');if(!in_array($type,['contribution','eventmenu_bonus','coupon','offer','adjustment'],true))throw new RuntimeException('Tipo de lançamento inválido.');$amount=$moneyToCents($_POST['amount']??0);if($amount===0)throw new RuntimeException('Informe o valor do lançamento.');$description=mb_substr(trim((string)($_POST['description']??'')),0,500);if($description==='')throw new RuntimeException('Informe a descrição.');$ref='impulsiona:'.bin2hex(random_bytes(12));Database::transaction(function(PDO$tx)use($tenantId,$type,$amount,$description,$ref):void{$s=$tx->prepare('SELECT tenant_id FROM marketplace_promotion_accounts WHERE tenant_id=?');$s->execute([$tenantId]);if(!$s->fetchColumn())$tx->prepare('INSERT INTO marketplace_promotion_accounts (tenant_id,participates,balance_cents) VALUES (?,1,0)')->execute([$tenantId]);$tx->prepare('INSERT INTO marketplace_promotion_ledger (tenant_id,entry_type,amount_cents,description,reference_key) VALUES (?,?,?,?,?)')->execute([$tenantId,$type,$amount,$description,$ref]);$tx->prepare('UPDATE marketplace_promotion_accounts SET balance_cents=balance_cents+?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=?')->execute([$amount,$tenantId]);});Auth::audit('marketplace.impulsiona_entry','tenant',(string)$tenantId,['entry_type'=>$type,'amount_cents'=>$amount]);em_flash('ok','Lançamento registrado no EventMenu Impulsiona.');em_go('marketplace-finance',['company'=>$tenantId]);}
