]??0))?></strong><small><?=em_money((int)($company['commissions']['paid']??0))?> paga</small></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="marketplace-tenant-save"><input type="hidden" name="tenant_id" value="<?=(int)$company['id']?>"><input type="hidden" name="return_tab" value="companies"><label class="checkbox"><input type="checkbox" name="participates"<?=em_checked((int)($company['participates']??0))?>> Participar do EventMenu Delivery</label><label>Situação<select name="marketplace_status"><option value="active"<?=em_selected($company['marketplace_status']??'inactive','active')?>>Ativa</option><option value="suspended"<?=em_selected($company['marketplace_status']??'','suspended')?>>Suspensa</option><option value="inactive"<?=em_selected($company['marketplace_status']??'','inactive')?>>Inativa</option></select></label><label>Cidade<input name="city" value="<?=Security::e($company['city']??'')?>"></label><label>UF<input name="state" maxlength="2" value="<?=Security::e($company['state']??'')?>"></label><button class="primary">Salvar participação</button></form><?php if($company['current_rule']):?><p class="muted">Taxa vigente agora: <strong><?=$percent((int)$company['current_rule']['rate_bps'])?></strong> · <?=Security::e($company['current_rule']['name'])?>. Pedidos antigos mantêm a taxa gravada no momento da compra.</p><?php endif;?><div class="grid admin-two-col"><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="impulsiona-toggle"><input type="hidden" name="tenant_id" value="<?=(int)$company['id']?>"><label class="checkbox"><input type="checkbox" name="participates"<?=em_checked((int)($company['impulsiona']['participates']??0))?>> Participa do EventMenu Impulsiona</label><p>Saldo: <strong><?=em_money((int)($company['impulsiona']['balance_cents']??0))?></strong></p><button class="secondary">Salvar</button></form><form method="post" class="card form-grid"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="impulsiona-entry"><input type="hidden" name="tenant_id" value="<?=(int)$company['id']?>"><label>Tipo<select name="entry_type"><option value="contribution">Aporte</option><option value="eventmenu_bonus">Bônus EventMenu</option><option value="coupon">Cupom</option><option value="offer">Oferta</option><option value="adjustment">Ajuste</option></select></label><label>Valor<input name="amount" inputmode="decimal" placeholder="100,00"></label><label class="span-2">Descrição<input name="description" required></label><button class="secondary span-2">Registrar lançamento</button></form></div></section><?php endif;?><?php endif;?>
<?php if($tab==='rules'):?><div class="grid admin-two-col"><section class="card"><span class="eyebrow">REGRA DE COMISSÃO</span><h2>Nova taxa ou campanha</h2><p class="muted">0% cria isenção. Datas permitem promoções temporárias. Maior prioridade vence; em empate, a regra mais específica vence.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="marketplace-rule-save"><input type="hidden" name="return_tab" value="rules"><label class="span-2">Nome<input name="name" required placeholder="Ex.: Lançamento 60 dias grátis"></label><label>Aplicar por<select name="scope_type"><option value="default">Padrão da plataforma</option><option value="tenant">Empresa</option><option value="city">Cidade</option><option value="state">Estado</option><option value="plan">Plano</option><option value="campaign">Campanha</option></select></label><label>Taxa (%)<input name="rate_percent" inputmode="decimal" required placeholder="4,00"></label><label>Empresa<select name="tenant_id"><option value="0">Selecione quando necessário</option><?php foreach($companies as$c):?><option value="<?=(int)$c['id']?>"><?=Security::e($c['name'])?></option><?php endforeach;?></select></label><label>Cidade<input name="city"></label><label>Estado<input name="state" maxlength="2"></label><label>Plano<select name="plan_code"><option value="">Selecione</option><?php foreach($plans as$p):?><option value="<?=Security::e($p['code'])?>"><?=Security::e($p['name'])?></option><?php endforeach;?></select></label><label>Campanha<input name="campaign_code" placeholder="EX.: INAUGURACAO"></label><label>Prioridade<input type="number" name="priority" value="0"></label><label>Início<input type="datetime-local" name="starts_at"></label><label>Fim<input type="datetime-local" name="ends_at"></label><button class="primary span-2">Salvar regra</button></form></section><section class="card"><span class="eyebrow">REGRAS ATUAIS</span><h2>Taxas configuradas</h2><?php foreach($rules as$r):?><div class="list-row"><div><strong><?=Security::e($r['name'])?></strong><small><?=Security::e($r['scope_type'])?><?=!empty($r['tenant_name'])?' · '.Security::e($r['tenant_name']):''?> · prioridade <?=(int)$r['priority']?><?php if($r['starts_at']||$r['ends_at']):?> · <?=Security::e((string)($r['starts_at']??'início livre'))?> → <?=Security::e((string)($r['ends_at']??'sem fim'))?><?php endif;?></small></div><div><strong><?=$percent((int)$r['rate_bps'])?></strong><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="marketplace-rule-toggle"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="active" value="<?=(int)$r['active']===1?0:1?>"><button class="button secondary compact"><?=(int)$r['active']===1?'Pausar':'Ativar'?></button></form></div></div><?php endforeach;?></section></div><?php endif;?>
<?php if($tab==='invoices'):?><section class="card"><div class="section-head"><div><span class="eyebrow">FATURAS</span><h2>Mensalidade + EventMenu Delivery + ajustes</h2></div><form method="post" class="actions"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="invoice-generate"><input type="hidden" name="return_tab" value="invoices"><select name="tenant_id" required><option value="">Empresa</option><?php foreach($companies as$c):?><option value="<?=(int)$c['id']?>"><?=Security::e($c['name'])?></option><?php endforeach;?></select><input type="date" name="period_start" value="<?=gmdate('Y-m-01')?>" required><input type="date" name="period_end" value="<?=gmdate('Y-m-t')?>" required><input type="datetime-local" name="due_at"><button class="primary">Gerar/atualizar fatura</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Empresa</th><th>Período</th><th>Status</th><th>Total</th><th>Vencimento</th><th></th></tr></thead><tbody><?php foreach($invoices as$i):?><tr><td><?=Security::e($i['tenant_name'])?></td><td><?=Security::e($i['period_start'].' a '.$i['period_end'])?></td><td><?=Security::e($statusLabel[$i['status']]??$i['status'])?></td><td><strong><?=em_money($i['total_cents'])?></strong></td><td><?=Security::e((string)($i['due_at']??'—'))?></td><td><a class="button secondary compact" href="<?=Security::e(app_url('?route=marketplace-finance&tab=invoices&invoice='.(int)$i['id']))?>">Detalhar</a></td></tr><?php endforeach;?></tbody></table></div></section><?php if($invoice):?><section class="card" style="margin-top:18px"><div class="section-head"><div><span class="eyebrow">FATURA #<?=(int)$invoice['id']?></span><h2><?=Security::e($invoice['tenant_name'])?></h2><p><?=Security::e($invoice['period_start'].' a '.$invoice['period_end'])?> · <?=Security::e($statusLabel[$invoice['status']]??$invoice['status'])?></p></div><strong style="font-size:1.6rem"><?=em_money($invoice['total_cents'])?></strong></div><div class="table-wrap"><table class="table"><thead><tr><th>Composição</th><th>Pedido</th><th>Base</th><th>Taxa</th><th>Valor</th></tr></thead><tbody><?php foreach($invoice['items'] as$item):?><tr><td><?=Security::e($item['description'])?></td><td><?=!empty($item['order_id'])?'#'.(int)$item['order_id']:'—'?></td><td><?=isset($item['calculation_base_cents'])&&$item['calculation_base_cents']!==null?em_money((int)$item['calculation_base_cents']):'—'?></td><td><?=isset($item['commission_bps'])&&$item['commission_bps']!==null?$percent((int)$item['commission_bps']):'—'?></td><td><?=em_money((int)$item['amount_cents'])?></td></tr><?php endforeach;?></tbody></table></div><div class="metric-grid"><div class="metric-card"><span>Serviços/cobranças</span><strong><?=em_money($invoice['subtotal_cents'])?></strong></div><div class="metric-card"><span>Créditos</span><strong>-<?=em_money($invoice['credits_cents'])?></strong></div><div class="metric-card"><span>Total</span><strong><?=em_money($invoice['total_cents'])?></strong></div></div><?php if(!in_array($invoice['status'],['paid','cancelled'],true)):?><div class="grid admin-two-col"><form method="post" class="card form-grid"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="invoice-adjustment"><input type="hidden" name="invoice_id" value="<?=(int)$invoice['id']?>"><input type="hidden" name="tenant_id" value="<?=(int)$invoice['tenant_id']?>"><label>Tipo<select name="kind"><option value="service">Outro serviço</option><option value="credit">Crédito/ajuste</option></select></label><label>Valor<input name="amount" required inputmode="decimal"></label><label class="span-2">Descrição<input name="description" required></label><button class="secondary span-2">Adicionar à fatura</button></form><div class="card actions"><form method="post"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="invoice-issue"><input type="hidden" name="invoice_id" value="<?=(int)$invoice['id']?>"><label>Vencimento<input type="datetime-local" name="due_at"></label><button class="primary">Emitir fatura</button></form><?php if(in_array($invoice['status'],['open','overdue'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="invoice-paid"><input type="hidden" name="invoice_id" value="<?=(int)$invoice['id']?>"><button class="primary">Marcar como paga</button></form><?php endif;?></div></div><?php endif;?></section><?php endif;?><?php endif;?>
<?php em_footer(); ?>
